  }
  ```

**useFileBrowserActions.handleDropOnFolder:**
- **useFileBrowserActions.ts** (lines 349–367):
  ```typescript
  const handleDropOnFolder = useCallback(
    async (
      items: Array<{ id: string; type: 'file' | 'folder' }>,
      sourceParentId: string,
      destFolderId: string
    ) => {
      try {
